// Payload contract (see backend/app/execution/adapters/n8n_calendar.py):
// POST body = { request_id, plan_id, action_id, action: { tool, operation, parameters: { title, start_datetime, end_datetime, timezone } } }.
// The Webhook node always nests the actual POST body under `.body`
// (alongside headers/params/query) - unwrap it here rather than treating
// the whole wrapper as the payload.
const body = $input.item.json.body;
const action = body.action || {};
const params = action.parameters || {};

if (action.tool !== 'calendar' || action.operation !== 'create_event') {
  throw new Error(`Unsupported action for this workflow: expected calendar.create_event, got ${action.tool}.${action.operation}`);
}
if (!params.title || !params.start_datetime) {
  throw new Error('Missing required parameters: title and start_datetime are required');
}

return {
  json: {
    request_id: body.request_id,
    plan_id: body.plan_id,
    action_id: body.action_id,
    title: params.title,
    start_datetime: params.start_datetime,
    end_datetime: params.end_datetime || params.start_datetime,
    timezone: params.timezone || 'UTC',
  },
};
